# -*- coding: utf-8 -*-
import io, os, sys, base64
BASE = sys.argv[1] if len(sys.argv) > 1 else "."
MARK = "HARITA_YENI_V1"
REL = "shells/saha.js"
path = os.path.join(BASE, REL)
with io.open(path, encoding="utf-8") as f: orig = f.read()
if MARK in orig:
    print("SKIP (zaten var):", REL); raise SystemExit

CORE = base64.b64decode("").decode("utf-8")
CSS  = base64.b64decode("").decode("utf-8")
BOOT = base64.b64decode("").decode("utf-8")

s = orig

# ---- Edit A: SECTION 1 markup -> hy-host (iki benzersiz yorum arasi slice) ----
S1 = "<!-- ── SECTION 1: MAP"
S2 = "<!-- ── SECTION 2: SAHA"
i = s.find(S1); j = s.find(S2)
assert i != -1 and j != -1 and i < j, "SECTION markerlari bulunamadi"
NEW1 = ('<!-- ── SECTION 1: MAP (yeni tasarim — HARITA_YENI_V1) ── -->\n'
        '        <div id="hy-host" style="margin-bottom:16px;min-height:60vh"></div>\n\n'
        '        ')
s = s[:i] + NEW1 + s[j:]

# ---- Edit B: loadHarita() sonrasi IIFE (Ebat yorumundan once) ----
EB = "// ── Ebat typeahead"
assert s.count(EB) == 1, "Ebat anchor tekil degil"
IIFE = ('/* HARITA_YENI_V1 — yeni harita (SECTION 1); Saha Sesi (SECTION 2) dokunulmadi */\n'
        '    (function(){\n'
        '      if(!document.getElementById("hy-css-v1")){var st=document.createElement("style");st.id="hy-css-v1";st.textContent=`' + CSS + '`;document.head.appendChild(st);}\n'
        '      ' + CORE + '\n'
        '      ' + BOOT + '\n'
        '    })();\n\n'
        '    ')
s = s.replace(EB, IIFE + EB, 1)

if not os.path.exists(path + ".haritayenibak"):
    with io.open(path + ".haritayenibak", "w", encoding="utf-8") as f: f.write(orig)
with io.open(path, "w", encoding="utf-8") as f: f.write(s)
print("OK", REL, "| YENI:", s.count(MARK))
